cd /workspace && python3 - <<'PY'
import os,stat
for root,dirs,files in os.walk('src'):
 for n in dirs+files:
  p=os.path.join(root,n);st=os.lstat(p)
  if not (stat.S_ISDIR(st.st_mode) or stat.S_ISREG(st.st_mode)):print('bad',p)
  if stat.S_ISREG(st.st_mode) and st.st_nlink!=1:print('nlink',p)
print('ok')
PY
